    public function save_2fa_settings($user_id) {
        if (!current_user_can('edit_user', $user_id)) {
            return;
        }

        $enabled = isset($_POST['wpec_2fa_enabled']) ? 'yes' : 'no';
        update_user_meta($user_id, 'wpec_2fa_enabled', $enabled);

        if ($enabled === 'yes' && empty(get_user_meta($user_id, 'wpec_2fa_secret', true))) {
            $secret = $this->generate_secret();
            update_user_meta($user_id, 'wpec_2fa_secret', $secret);
        }
    }

    public function ajax_verify_2fa() {
        check_ajax_referer('wpec_verify_2fa_' . $_POST['user_id'], 'nonce');

        if (!current_user_can('edit_user', $_POST['user_id'])) {
            wp_send_json_error(['message' => __('Permisos insuficientes', 'wp-extreme-customize')]);
        }

        $code = sanitize_text_field($_POST['code']);
        $secret = get_user_meta($_POST['user_id'], 'wpec_2fa_secret', true);

        if (empty($secret)) {
            wp_send_json_error(['message' => __('No hay clave secreta configurada', 'wp-extreme-customize')]);
        }

        // Verificar código TOTP
        if ($this->verify_totp($code, $secret)) {
            wp_send_json_success(['message' => __('Código verificado correctamente', 'wp-extreme-customize')]);
        } else {
            wp_send_json_error(['message' => __('Código inválido', 'wp-extreme-customize')]);
        }
    }

    private function verify_totp($code, $secret) {
        // Implementación simple de TOTP
        $time_slice = floor(time() / 30);
        $secret = base64_decode(strtoupper($secret));

        for ($i = -1; $i <= 1; $i++) {
            $calculated = $this->generate_totp($secret, $time_slice + $i);
            if (hash_equals($calculated, $code)) {
                return true;
            }
        }

        return false;
    }

    private function generate_totp($secret, $time_slice) {
        $time = pack('N*', 0) . pack('N*', $time_slice);
        $hmac = hash_hmac('sha1', $time, $secret, true);
        $offset = ord(substr($hmac, -1)) & 0x0F;
        $code = (
            ((ord($hmac[$offset]) & 0x7F) << 24) |
            ((ord($hmac[$offset+1]) & 0xFF) << 16) |
            ((ord($hmac[$offset+2]) & 0xFF) << 8) |
            (ord($hmac[$offset+3]) & 0xFF)
        ) % 1000000;

        return str_pad($code, 6, '0', STR_PAD_LEFT);
    }

    private function generate_secret() {
        $bytes = random_bytes(20);
        return base64_encode($bytes);
    }

    public function add_security_headers() {
        if (!$this->get_setting('enable_security_headers', true)) {
            return;
        }

        header('X-Content-Type-Options: nosniff');
        header('X-Frame-Options: SAMEORIGIN');
        header('X-XSS-Protection: 1; mode=block');
        header('Referrer-Policy: strict-origin-when-cross-origin');
        header('Permissions-Policy: geolocation=(), microphone=(), camera=()');

        if ($this->get_setting('enable_hsts', false)) {
            header('Strict-Transport-Security: max-age=31536000; includeSubDomains; preload');
        }

        if ($this->get_setting('enable_csp', false)) {
            $csp = $this->get_setting('csp_policy', "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; font-src 'self' data:;");
            header('Content-Security-Policy: ' . $csp);
        }
    }

    public function restrict_rest_api($result) {
        if (!$this->get_setting('restrict_rest_api', false)) {
            return $result;
        }

        if (!is_user_logged_in()) {
            return new WP_Error('rest_not_logged_in', __('No tienes permiso para acceder a la API REST', 'wp-extreme-customize'), ['status' => 401]);
        }

        return $result;
    }

    public function remove_pingback($methods) {
        if (!$this->get_setting('disable_pingbacks', true)) {
            return $methods;
        }

        unset($methods['pingback.ping']);
        return $methods;
    }

    public function force_https() {
        if (!$this->get_setting('force_https', false) || is_ssl()) {
            return;
        }

        if (strpos($_SERVER['SERVER_NAME'], 'localhost') === false && strpos($_SERVER['SERVER_NAME'], '127.0.0.1') === false) {
            wp_redirect('https://' . $_SERVER['HTTP_HOST'] . $_SERVER['REQUEST_URI'], 301);
            exit;
        }
    }

    public function disable_editors() {
        if ($this->get_setting('disable_file_edit', true)) {
            define('DISALLOW_FILE_EDIT', true);
        }

        if ($this->get_setting('disable_plugin_install', false)) {
            define('DISALLOW_FILE_MODS', true);
        }
    }

    public function add_security_menu() {
