        data.action = action;
        data.nonce = wpec_ajax.nonce;

        $.post(wpec_ajax.ajax_url, data, function(response) {
            if (callback) callback(response);
        }).fail(function() {
            if (callback) callback({success: false, data: {message: wpec_ajax.strings.error}});
        });
    };

    // Notificaciones toast
    window.wpecToast = function(message, type) {
        type = type || 'success';
        var $toast = $('<div class="wpec-toast wpec-toast-' + type + '">' + message + '</div>');
        $('body').append($toast);

        $toast.fadeIn(300);

        setTimeout(function() {
            $toast.fadeOut(300, function() {
                $(this).remove();
            });
        }, 3000);
    };

